    int age;
} Person;
```

Массив из нескольких `Person` + функции.

## Финальный пример

```c
#include <stdio.h>
#include <string.h>

typedef struct {
    char name[30];
    int age;
} Person;

Person oldest(Person arr[], int n) {
    Person result = arr[0];
    for (int i = 1; i < n; i++) {
        if (arr[i].age > result.age) result = arr[i];
    }
    return result;
}

int main(void) {
    Person people[] = {{"Иван", 25}, {"Мария", 30}, {"Пётр", 28}};
    Person o = oldest(people, 3);
    printf("Старший: %s (%d)\n", o.name, o.age);
    return 0;
}
```

